package com.onlinebank.corporate.controller;

import com.onlinebank.corporate.entity.BankAccount;
import com.onlinebank.corporate.repository.BankAccountRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/corporate-accounts")
public class BankAccountController {

    private final BankAccountRepository bankAccountRepository;

    public BankAccountController(BankAccountRepository bankAccountRepository) {
        this.bankAccountRepository = bankAccountRepository;
    }

    @GetMapping("/{accountId}")
    public ResponseEntity<BankAccount> getAccountDetails(@PathVariable Long accountId) {
        // Returns JPA entity directly; Jackson serializes lazy-loaded @OneToMany corporateCards collection
        BankAccount account = bankAccountRepository.findById(accountId)
                .orElseThrow(() -> new IllegalArgumentException("Account not found"));
        return ResponseEntity.ok(account);
    }
}

corrected_code:
package com.onlinebank.corporate.controller;

import com.onlinebank.corporate.dto.BankAccountSummaryDto;
import com.onlinebank.corporate.entity.BankAccount;
import com.onlinebank.corporate.repository.BankAccountRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/corporate-accounts")
public class BankAccountController {

    private final BankAccountRepository bankAccountRepository;

    public BankAccountController(BankAccountRepository bankAccountRepository) {
        this.bankAccountRepository = bankAccountRepository;
    }

    @GetMapping("/{accountId}")
    public ResponseEntity<BankAccountSummaryDto> getAccountDetails(@PathVariable Long accountId) {
        BankAccount account = bankAccountRepository.findById(accountId)
                .orElseThrow(() -> new IllegalArgumentException("Account not found"));
        // Project into DTO without triggering or exposing child cards collection
        BankAccountSummaryDto dto = new BankAccountSummaryDto(
                account.getId(),
                account.getAccountNumber(),
                account.getBalance(),
                account.getCurrency()
        );
        return ResponseEntity.ok(dto);
    }
}
